files.plan/prepare.ts:
export default function prepare(tasks: Task[]): State {
const ids = tasks.map(t => t.id);
if (new Set(ids).size !== ids.length) throw new Error("duplicate task IDs");
return {tasks: tasks, order: [], blocked: [], finished: tasks.length === 0};
}

files.plan/step/advance.ts:
export default function advance(state: State, chosen: string): State {
const task = state.tasks.find(t => t.id === chosen);
if (!task || state.order.includes(task.id) || !task.needs.every(n => state.order.includes(n)))
  throw new Error("chosen task is not ready");
const order = [...state.order, task.id];
return {...state, order, finished: order.length === state.tasks.length};
}

files.plan/step/ready_tasks.ts:
export default function ready_tasks(state: State): Task[] {
const done = new Set(state.order);
return state.tasks.filter(t => !done.has(t.id) && t.needs.every(n => done.has(n)));
}

files.plan/step/stall.ts:
export default function stall(state: State): State {
return {...state, blocked: state.tasks.filter(t => !state.order.includes(t.id)).map(t => t.id), finished: true};
}

