files.process_mail/handle_mail.nl:
---
description: Decide what to do with one email; dates from my landlord go into the calendar.
args:
  email: string
returns: Decision
---
function handle_mail(email) -> Decision

  landlord = from_landlord(email)
  if not landlord:
      return { action: "archive", date: "" }
  date = find_date(email)                               # "" when the email names no date
  if date is "":
      return { action: "reply_later", date: "" }
  add_to_calendar(date, email)                          # effect
  return { action: "calendar", date }

files.process_mail/handle_mail/add_to_calendar:
import { calendar } from 'natlang:services';
export default function add_to_calendar(date: string, email: string): boolean {
calendar.add({ date: date, note: email.slice(0, 80) })
return true
}

files.process_mail/tally_actions.ts:
export default function tally_actions(decisions: Decision[]): MailReport {
const n = a => decisions.filter(d => d.action === a).length
return { calendar: n("calendar"), reply_later: n("reply_later"), archived: n("archive") }
}

