export type Request = { id: string, method: string, path: string, headers: Record<string, string>, body: string };
export type Parsed = { id: string, method: string, path: string, query: Record<string, string>, form: Record<string, string>, session_id: string };
export type Route = { kind: "static" | "page" | "form" | "not_found" | "method_not_allowed", name: string, purpose: string, asset: string };
export type RouteDef = { path: string, methods: string[], kind: "static" | "page" | "form", purpose: string, asset?: string };
export type Entry = { author: string, message: string };
export type Session = { id: string, visits: number, name: string };
export type Site = { name: string, about: string, routes: RouteDef[], assets: Record<string, string>, entries: Entry[], sessions: Record<string, Session>, log: string[] };
export type Review = { accept: boolean, reason: string, author: string, message: string };
export type Response = { status: number, headers: Record<string, string>, body: string };

files.run/handle/apply_submission.ts:
export default function apply_submission(acc: Site, review: Review): Site {
if (!review.accept || !review.message.trim()) return acc
const entry = { author: review.author.trim().slice(0, 60) || "anonymous", message: review.message.trim().slice(0, 500) }
return { ...acc, entries: acc.entries.concat([entry]).slice(-50) }
}

files.run/handle/error_response.ts:
export default function error_response(route: Route): Response {
const notAllowed = route.kind === "method_not_allowed"
return { status: notAllowed ? 405 : 404, headers: Object.assign({ "Content-Type": "text/html; charset=utf-8" }, notAllowed ? { "Allow": route.purpose } : {}),
         body: `<!doctype html><title>${notAllowed ? 405 : 404}</title><h1>${notAllowed ? "Method not allowed" : "Not found"}</h1><p><a href="/">home</a></p>` }
}

files.run/handle/log_request.ts:
export default function log_request(site: Site, req: Parsed, session: Session, response: Response): Site {
const line = `${req.method} ${req.path} -> ${response.status} (${response.body.length} bytes, session ${session.id}, visit ${session.visits})`
return { ...site, sessions: { ...site.sessions, [session.id]: session }, log: site.log.concat([line]).slice(-200) }
}

files.run/handle/match_route.ts:
export default function match_route(routes: RouteDef[], req: Parsed): Route {
const hit = routes.find(r => r.path === req.path)
if (!hit) return { kind: "not_found", name: req.path, purpose: "", asset: "" }
if (!hit.methods.includes(req.method)) return { kind: "method_not_allowed", name: hit.path, purpose: hit.methods.join(", "), asset: "" }
return { kind: hit.kind, name: hit.path, purpose: hit.purpose, asset: hit.asset || "" }
}

files.run/handle/parse_request.ts:
export default function parse_request(item: Request): Parsed {
const dec = s => { try { return decodeURIComponent(s.replace(/\+/g, " ")) } catch (e) { return s } }
const pairs = s => Object.fromEntries((s || "").split("&").filter(Boolean).map(p => { const i = p.indexOf("="); return i < 0 ? [dec(p), ""] : [dec(p.slice(0, i)), dec(p.slice(i + 1))] }))
const [path, qs] = item.path.split("?")
const cookie = Object.entries(item.headers).find(([k]) => lower(k) === "cookie")
const sid = cookie ? (cookie[1].match(/(?:^|;\s*)sid=([A-Za-z0-9_-]+)/) || [])[1] : ""
return { id: item.id, method: item.method.toUpperCase(), path: path.replace(/\/+$/, "") || "/", query: pairs(qs),
         form: item.method.toUpperCase() === "POST" ? pairs(item.body) : {}, session_id: sid || "" }
}

files.run/handle/respond.ts:
import { http } from 'natlang:services';
export default function respond(id: string, response: Response): boolean {
http.respond(id, response)
return true
}

files.run/handle/session_for.ts:
export default function session_for(acc: Site, req: Parsed): Session {
const old = acc.sessions[req.session_id]
if (old) return { ...old, visits: old.visits + 1 }
return { id: "s" + (Object.keys(acc.sessions).length + 1) + "x" + req.id.replace(/[^A-Za-z0-9]/g, ""), visits: 1, name: "" }
}

files.run/handle/static_response.ts:
export default function static_response(acc: Site, route: Route): Response {
const body = acc.assets[route.asset]
if (body === undefined) return { status: 404, headers: { "Content-Type": "text/plain; charset=utf-8" }, body: "Not found" }
const type = route.asset.endsWith(".css") ? "text/css" : route.asset.endsWith(".txt") ? "text/plain" : "text/html"
return { status: 200, headers: { "Content-Type": type + "; charset=utf-8", "Cache-Control": "max-age=3600" }, body }
}

files.run/handle/wrap_page.ts:
export default function wrap_page(acc: Site, route: Route, content: string, session: Session): Response {
const esc = s => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
const safe = content.replace(/<\s*script[\s\S]*?<\s*\/\s*script\s*>/gi, "").replace(/\son\w+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, "")
const nav = acc.routes.filter(r => r.kind === "page").map(r => `<a href="${r.path}">${esc(r.path === "/" ? "home" : r.path.slice(1))}</a>`).join(" · ")
const html = `<!doctype html><html><head><meta charset="utf-8"><title>${esc(acc.name)}</title><link rel="stylesheet" href="/style.css"></head>` +
             `<body><header><h1>${esc(acc.name)}</h1><nav>${nav}</nav></header><main>${safe}</main></body></html>`
return { status: 200, headers: { "Content-Type": "text/html; charset=utf-8", "Set-Cookie": `sid=${session.id}; Path=/; HttpOnly; SameSite=Lax` }, body: html }
}

